{"content":"import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

/// Экран дашборда: при открытии параллельно запрашивает свежий курс валют
/// и свежую ленту новостей. Пока данные грузятся — индикатор прогресса.
class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late final Future<Map<String, dynamic>> _dashboardFuture;

  @override
  void initState() {
    super.initState();
    _dashboardFuture = _loadData();
  }

  static Future<Map<String, dynamic>> _loadData() async {
    final currencyRepository = CurrencyRepositoryProvider.of();
    final newsRepository = NewsRepositoryProvider.of();

    // Параллельные запросы: свежий курс + свежая лента новостей
    return Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<FutureResult> results) => {
          'currencies': (results[0] as CurrencyPage).items,
          'news': results[1] as List<NewsModel>,
        });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<Map<String, dynamic>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<Map<String, dynamic>> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          if (!snapshot.hasData || snapshot.data!.isEmpty) {
            return Center(
              child: Text(loc.loading),
            );
          }

          final List<CurrencyModel> currencies = snapshot.data!['currencies'];
          final List<NewsModel> news = snapshot.data!['news'];

          return SingleChildScrollView(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                // Секция курса валют
                Text(loc.currencyRate, style: Theme.of(context).textTheme.titleLarge),
                const SizedBox(height: 8),
                if (currencies.isEmpty)
                  Center(child: Text(loc.loading))
                else ...[
                  ListView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: currencies.length > 5 ? 5 : currencies.length,
                    itemBuilder: (BuildContext context, int index) {
                      final CurrencyModel currency = currencies[index];
                      return Padding(
                        padding: const EdgeInsets.symmetric(vertical: 4),
                        child: Text('${currency.name}: ${currency.value}'),
                      );
                    },
                  ),
                ],
                const Divider(height: 32),
                // Секция новостей
                Text(loc.news, style: Theme.of(context).textTheme.titleLarge),
                const SizedBox(height: 8),
                if (news.isEmpty)
                  Center(child: Text(loc.loading))
                else ...[
                  ListView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: news.length > 5 ? 5 : news.length,
                    itemBuilder: (BuildContext context, int index) {
                      final NewsModel item = news[index];
                      return Padding(
                        padding: const EdgeInsets.symmetric(vertical: 4),
                        child: Text(item.title),
                      );
                    },
                  ),
                ],
              ],
            ),
          );
        },
      ),
    );
  }
}
