import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final currencyItems = CurrencyPage(
      items: const [
        CurrencyModel(
          id: '1',
          nominal: 1,
          name: 'Доллар США',
          symbol: 'USD',
          value: 90.0,
          previousValue: 89.5,
        ),
      ],
      page: 0,
      hasMore: false,
    );

    final newsItems = const [
      NewsModel(title: 'Новость 1', link: 'https://example.com/1'),
    ];

    setUp(() {
      when(mockCurrencyRepository.fetchRates(any))
          .thenAnswer((_) async => currencyItems);
      when(mockNewsRepository.loadNewsFeed(any))
          .thenAnswer((_) async => newsItems);
    });

    testWidgets('should display currency and news data when loaded', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        ),
      );

      await tester.pumpAndSettle();

      // После завершения Future.wait — данные отображены
      expect(find.textContaining('Доллар США'), findsOneWidget);
      expect(find.text('Новость 1'), findsOneWidget);
    });

    testWidgets('should display app bar title', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('Дашборд'), findsOneWidget);
    });
  });
}
